inline void throw_file_op_error(int error_code, int kind, int a = 0, int b = 0) {
  formatter<std::filesystem::path, char> coordinator;
  if (kind == 2) {
    coordinator.raise_close_error(error_code);
  } else if (kind == 5 || kind == 6) {
    coordinator.raise_io_error(error_code, kind == 5);
