    coordinator.raise_dup_error(error_code, a, kind == 8 ? b : -1);
  } else if (kind == 9) {
    coordinator.raise_pipe_error(error_code);
  } else {
    coordinator.raise_system_error(error_code, kind, a, b);
  }
}
#else
inline void throw_path_io_error(int error_code, const char* path) {
